//! MAC address → vendor, from the IEEE registries bundled in the binary
//! (`data/oui.tsv.gz`, regenerated by `scripts/update-oui.mjs`).
//!
//! The list holds 24-bit (MA-L), 28-bit (MA-M) and 36-bit (MA-S) prefixes;
//! the longest match wins, as small blocks sit inside an "IEEE Registration
//! Authority" 24-bit block.

use std::collections::HashMap;
use std::io::Read;
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("../../data/oui.tsv.gz");

/// Prefix (as an integer of its hex digits) → vendor, one map per length.
struct Table {
    by_len: [HashMap<u64, Box<str>>; 3],
}

const LENGTHS: [usize; 3] = [9, 7, 6];

fn table() -> &'static Table {
    static T: OnceLock<Table> = OnceLock::new();
    T.get_or_init(|| {
        let mut text = String::new();
        let mut by_len: [HashMap<u64, Box<str>>; 3] = Default::default();
        if flate2::read::GzDecoder::new(DATA)
            .read_to_string(&mut text)
            .is_err()
        {
            log::warn!("bundled vendor list unreadable");
            return Table { by_len };
        }
        for line in text.lines() {
            let Some((prefix, vendor)) = line.split_once('\t') else {
                continue;
            };
            let Some(slot) = LENGTHS.iter().position(|&l| l == prefix.len()) else {
                continue;
            };
            if let Ok(p) = u64::from_str_radix(prefix, 16) {
                by_len[slot].insert(p, vendor.into());
            }
        }
        Table { by_len }
    })
}

/// The vendor that registered this MAC's prefix. `None` for unknown and for
/// locally administered (randomised) addresses, which carry no vendor.
pub fn vendor(mac: &[u8; 6]) -> Option<&'static str> {
    if is_randomized(mac) {
        return None;
    }
    let full = mac.iter().fold(0u64, |a, &b| (a << 8) | u64::from(b)); // 12 hex digits
    let t = table();
    LENGTHS.iter().enumerate().find_map(|(slot, &len)| {
        let prefix = full >> (4 * (12 - len));
        t.by_len[slot].get(&prefix).map(|v| &**v)
    })
}

/// Locally administered address (bit 1 of the first byte): phones and
/// computers use random ones per network for privacy.
pub fn is_randomized(mac: &[u8; 6]) -> bool {
    mac[0] & 0x02 != 0
}

/// Parse "aa:bb:cc:dd:ee:ff" or "aa-bb-…". Test-only for now.
#[cfg(test)]
pub fn parse_mac(s: &str) -> Option<[u8; 6]> {
    let mut out = [0u8; 6];
    let mut parts = s.split([':', '-']);
    for b in &mut out {
        *b = u8::from_str_radix(parts.next()?, 16).ok()?;
    }
    parts.next().is_none().then_some(out)
}

pub use crate::util::format_mac;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_vendors() {
        // 24-bit blocks (MA-L).
        assert_eq!(
            vendor(&parse_mac("b8:27:eb:00:00:01").unwrap()),
            Some("Raspberry Pi Foundation")
        );
        assert_eq!(
            vendor(&parse_mac("3c:07:54:12:34:56").unwrap()),
            Some("Apple")
        );
        // Two 36-bit blocks (MA-S) that share a 24-bit prefix resolve to
        // different registrants: the longest prefix must win, not the /24.
        let a = vendor(&parse_mac("00:1b:c5:00:00:00").unwrap());
        let b = vendor(&parse_mac("00:1b:c5:00:10:00").unwrap());
        assert!(
            a.is_some() && b.is_some() && a != b,
            "MA-S blocks: {a:?} vs {b:?}"
        );
        assert!(table().by_len.iter().map(HashMap::len).sum::<usize>() > 40_000);
    }

    #[test]
    fn randomized_and_parsing() {
        let r = parse_mac("da:a1:19:00:00:01").unwrap();
        assert!(is_randomized(&r));
        assert_eq!(vendor(&r), None);
        assert_eq!(
            parse_mac("00-1A-11-AA-BB-CC")
                .map(|m| format_mac(&m))
                .as_deref(),
            Some("00:1a:11:aa:bb:cc")
        );
        assert!(parse_mac("00:1a:11").is_none());
        assert!(parse_mac("00:1a:11:aa:bb:cc:dd").is_none());
    }
}
